bool PreferencesWindow::on_page_message(const std::string& type, const json& payload)
{
    if (type == Agent::Protocol::kShellAction && payload.is_object() && payload.value("action", std::string()) == "close") {
        // The page closes a window opened for one task once it is done. A key
        // counts only once one is stored and the agent is on.
        AfterClose after;
        const std::string done = payload.value("done", std::string());
        if (m_request.close_when_done &&
            (done == "tool" || (done == "key" && wxGetApp().app_config->get("jusprin_agent", "enabled") == "true")))
            after.done = done;
        CallAfter([this, after] { close_for(after); });
        return true;
    }
    if (type == Agent::Protocol::kShellAction && payload.is_object() && payload.value("action", std::string()) == "open_server_page") {
        // Account's Get more credits, in the sheet the composer's opens,
        // here over this window. This page reads the balance again after; the
        // main window's screens read it when they come back on screen.
        const std::string page = payload.value("page", std::string());
        const std::string from = payload.value("from", std::string());
        CallAfter([this, page, from] {
            ServerSheet::open(this, page, from, [this] {
                if (m_view != nullptr)
                    m_view->host().refresh_account();
            });
        });
        return true;
    }
    if (type == Agent::Protocol::kShellAction && payload.is_object() && payload.value("action", std::string()) == "check_for_updates") {
        // Account's Get the new version…: the page turns to Updates itself.
        // This window is the Preferences that would be opened, so only the
        // check happens, and its answer reaches Updates as any check's does.
        get_new_version();
        return true;
