"""Serves the instrumented Home page; /cmd hands out one queued command, /log and /snap record what the page sends."""
import http.server, socketserver, sys, os, json, time
from pathlib import Path
root = Path(sys.argv[1]); port = int(sys.argv[2]); out = Path(sys.argv[3])
class H(http.server.SimpleHTTPRequestHandler):
    def __init__(self, *a, **k): super().__init__(*a, directory=str(root), **k)
    def log_message(self, *a): pass
    def _ok(self, body=b''):
        self.send_response(200); self.send_header('Access-Control-Allow-Origin', '*'); self.send_header('Content-Length', str(len(body))); self.end_headers(); self.wfile.write(body)
    def do_GET(self):
        if self.path.startswith('/cmd'):
            q = out / 'queue.txt'; lines = q.read_text().splitlines() if q.exists() else []
            cmd = lines[0] if lines else ''
            q.write_text('\n'.join(lines[1:]) + ('\n' if lines[1:] else ''))
            return self._ok(cmd.encode())
        return super().do_GET()
    def do_POST(self):
        n = int(self.headers.get('Content-Length') or 0); body = self.rfile.read(n).decode('utf-8', 'replace')
        if self.path.startswith('/snap'):
            (out / f'snap-{int(time.time()*1000)}.html').write_text(body)
        else:
            with open(out / 'log.txt', 'a') as f: f.write(f'{time.strftime("%H:%M:%S")} {self.path} {body}\n')
        return self._ok()
    def do_OPTIONS(self):
        self.send_response(200); self.send_header('Access-Control-Allow-Origin', '*'); self.send_header('Access-Control-Allow-Headers', '*'); self.end_headers()
socketserver.ThreadingTCPServer.allow_reuse_address = True
with socketserver.ThreadingTCPServer(('127.0.0.1', port), H) as s: s.serve_forever()
